use std::path::PathBuf;
use ingetrazo_core::camera::OrbitCamera;
use ingetrazo_render::vector_hlr::{parallel_visible_segments,LineKind};
fn main(){let root=PathBuf::from(std::env::args().nth(1).expect("fixture directory"));for entry in std::fs::read_dir(&root).unwrap(){let path=entry.unwrap().path();if !path.to_string_lossy().ends_with(".reference.json"){continue;}let reference:serde_json::Value=serde_json::from_slice(&std::fs::read(&path).unwrap()).unwrap();let name=reference["name"].as_str().unwrap();let scene=ingetrazo_formats::igz::load_igz(&root.join(format!("{name}.igz"))).unwrap();let camera:OrbitCamera=serde_json::from_value(reference["camera"].clone()).unwrap();let result=parallel_visible_segments(&scene,&camera);let world=result.iter().map(|s|[s.a.to_array(),s.b.to_array()]).collect::<Vec<_>>();let kinds=result.iter().map(|s|match s.kind{LineKind::Edge=>0,LineKind::Profile=>1,LineKind::Cut=>2}).collect::<Vec<_>>();std::fs::write(root.join(format!("{name}.rust.json")),serde_json::to_vec_pretty(&serde_json::json!({"world":world,"kinds":kinds})).unwrap()).unwrap();}}
